<?php
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/booking-functions.php';require_user();$user=current_user();$scheduleId=filter_var($_GET['schedule']??$_POST['schedule']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;$date=(string)($_GET['date']??$_POST['date']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$guestName=trim((string)($_POST['guest_name']??''));if(!valid_journey_date($date)){flash('Choose a valid journey date from today onward.');go('train-information.php');}
 if($guestName!==''&&!preg_match('/^[\p{L}\p{M} .\'-]{2,120}$/u',$guestName)){flash('Guest name must be 2–120 letters, spaces, apostrophes, or hyphens.');go('booking.php',['schedule'=>$scheduleId,'date'=>$date]);}
 try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT sc.schedule_id,sc.train_id,sc.valid_from,sc.valid_until,sc.service_days,t.train_name,t.train_code,r.route_name,r.route_id,r.origin_station_id,r.destination_station_id,o.station_name AS origin_name,d.station_name AS destination_name,sc.departure_time,sc.arrival_time FROM schedules sc JOIN trains t ON t.train_id=sc.train_id JOIN routes r ON r.route_id=sc.route_id JOIN stations o ON o.station_id=r.origin_station_id JOIN stations d ON d.station_id=r.destination_station_id WHERE sc.schedule_id=? AND sc.is_active=1 AND t.is_active=1 AND r.is_active=1 FOR UPDATE');$q->execute([$scheduleId]);$trip=$q->fetch();if(!$trip)throw new RuntimeException('That schedule is no longer available.');if(($trip['valid_from']&&$date<$trip['valid_from'])||($trip['valid_until']&&$date>$trip['valid_until']))throw new RuntimeException('That schedule does not run on the selected date.');$days=array_map('strtolower',array_map('trim',explode(',',(string)$trip['service_days'])));if(!in_array('daily',$days,true)&&!in_array(strtolower((new DateTimeImmutable($date))->format('D')),$days,true))throw new RuntimeException('That shuttle does not run on this day of the week.');
  $ref=strtoupper(bin2hex(random_bytes(6)));$q=$pdo->prepare('INSERT INTO booking_groups(booking_ref,host_user_id,active_host_user_id,schedule_id,journey_date) VALUES(?,?,?,?,?)');$q->execute([$ref,$user['user_id'],$user['user_id'],$scheduleId,$date]);$groupId=(int)$pdo->lastInsertId();$passengers=[['name'=>$user['full_name'],'category'=>$user['category'],'gender'=>$user['gender'],'guest'=>0]];if($guestName!=='')$passengers[]=['name'=>$guestName,'category'=>$user['category'],'gender'=>$user['gender'],'guest'=>1];
  $insert=$pdo->prepare('INSERT INTO bookings(booking_group_id,schedule_id,journey_date,passenger_name,category,gender,seat_id,seat_label,bogie_label,is_guest) VALUES(?,?,?,?,?,?,?,?,?,?)');foreach($passengers as $passenger){$seat=allocate_seat($pdo,$scheduleId,$date,$passenger['category'],$passenger['gender']);$insert->execute([$groupId,$scheduleId,$date,$passenger['name'],$passenger['category'],$passenger['gender'],$seat['seat_id'],$seat['seat_number'],$seat['bogie_code'],$passenger['guest']]);}$pdo->commit();go('ticket.php',['ref'=>$ref]);
 }catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();if($exception instanceof RuntimeException)$message=$exception->getMessage();elseif($exception instanceof PDOException&&(string)$exception->getCode()==='23000')$message='You already have a booking for this train and date, or a seat was just taken. Refresh availability and try again.';else $message='The booking could not be completed. Refresh availability and try again.';flash($message);go('booking.php',['schedule'=>$scheduleId,'date'=>$date]);}
}
if(!$scheduleId||!valid_journey_date($date)){flash('Select a valid train and journey date.');go('train-information.php');}
$q=$pdo->prepare('SELECT sc.*,t.train_name,t.train_code,r.route_name,r.origin_station_id,r.destination_station_id,o.station_name AS origin_name,d.station_name AS destination_name FROM schedules sc JOIN trains t ON t.train_id=sc.train_id JOIN routes r ON r.route_id=sc.route_id JOIN stations o ON o.station_id=r.origin_station_id JOIN stations d ON d.station_id=r.destination_station_id WHERE sc.schedule_id=? AND sc.is_active=1 AND t.is_active=1 AND r.is_active=1');$q->execute([$scheduleId]);$trip=$q->fetch();if(!$trip) {flash('Schedule not found.');go('train-information.php');}
$q=$pdo->prepare('SELECT s.seat_number FROM seats s JOIN bogies b ON b.bogie_id=s.bogie_id JOIN trains t ON t.train_id=b.train_id WHERE t.train_id=? AND b.category=? AND b.gender=? AND b.is_active=1 AND s.is_active=1 AND NOT EXISTS(SELECT 1 FROM bookings x WHERE x.schedule_id=? AND x.journey_date=? AND x.seat_id=s.seat_id AND x.status="Confirmed") ORDER BY s.seat_number');$q->execute([$trip['train_id'],$user['category'],$user['gender'],$scheduleId,$date]);$available=$q->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Book a seat';require __DIR__.'/includes/header.php';?>
<section class="content"><span class="eyebrow">SEAT RESERVATION</span><h1>Confirm your journey</h1><div class="booking"><div><span class="tag"><?=e($trip['train_code'])?></span><h3><?=e($trip['train_name'])?></h3><p><?=e($trip['origin_name'])?> → <?=e($trip['destination_name'])?> · <?=e($date)?></p><p><?=e(substr($trip['departure_time'],0,5))?>–<?=e(substr($trip['arrival_time'],0,5))?> · <?=e($user['category'])?> / <?=e($user['gender'])?> allocation</p></div><strong><?=count($available)?> seats left</strong></div><?php if(!$available):?><p>Your allocation is full for this journey.</p><?php else:?><form class="fields" method="post"><?php csrf_input();?><input type="hidden" name="schedule" value="<?=e($scheduleId)?>"><input type="hidden" name="date" value="<?=e($date)?>"><p>Your seat will be allocated automatically in your <?=e($user['category'])?> / <?=e($user['gender'])?> bogie. Seats already assigned to another passenger are excluded.</p><label>Guest name (optional)<input name="guest_name" maxlength="120" pattern="[A-Za-zÀ-ž .'-]{2,120}" placeholder="Guest travels in the same bogie"></label><button class="button">Confirm booking</button></form><?php endif?></section>
<?php require __DIR__.'/includes/footer.php'; ?>
